import os
import shutil
import json

def cleanup_cache():
    cache_dir_pattern = "__pycache__/*"
    for dir_path in os.listdir():
        if os.path.isdir(os.path.join(cache_dir_pattern, dir_path)):
            shutil.rmtree(os.path.join(cache_dir_pattern, dir_path))

if __name__ == "__main__":
    cleanup_cache()
